css:
.prep-doc{
  --bg:#ECF0ED; --surface:#FAFBF9; --ink:#1B2526; --muted:#55625E; --line:#C9D3CE;
  --jade:#1C6A51; --jade-tint:#E0ECE5; --jade-line:#A5C9B6;
  --copper:#94472A; --copper-tint:#F3E5DB; --copper-line:#DDB49C;
  --slate:#2A4865; --slate-tint:#E1E8EF; --slate-line:#B5C6D6;
  --boon:#B0421D; --orek:#5A4A8C; --vali:#8A5F0A;
  --paper:#F7F1E4; --paper-ink:#2B2218; --paper-line:#D8CBAE; --paper-label:#7C6A4C;
  --display:"IM Fell English","Iowan Old Style","Palatino Linotype",Georgia,serif;
  --display-sc:"IM Fell English SC","IM Fell English","Iowan Old Style",Georgia,serif;
  --read:"Alegreya","Iowan Old Style","Palatino Linotype",Georgia,serif;
  --sans:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"IBM Plex Mono",ui-monospace,Menlo,Consolas,monospace;
}
.prep-doc *{box-sizing:border-box}
.prep-doc{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.55}
.prep-doc .wrap{max-width:860px;margin:0 auto;padding-inline:18px;padding-block:0 80px}
.prep-doc h1, .prep-doc h2, .prep-doc h3, .prep-doc h4{text-wrap:balance;margin:0}
.prep-doc p{margin:0}
.prep-doc a{color:var(--jade)}
.prep-doc a:focus-visible, .prep-doc button:focus-visible, .prep-doc summary:focus-visible{outline:2px solid var(--jade);outline-offset:2px}
.prep-doc .rail{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(6px);border-bottom:1px solid var(--line)}
.prep-doc .rail-inner{max-width:860px;margin:0 auto;padding:8px 18px;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none}
.prep-doc .rail a{flex:0 0 auto;text-decoration:none;font-family:var(--mono);font-size:12px;color:var(--muted);padding:5px 10px;border:1px solid var(--line);border-radius:999px;background:var(--surface);white-space:nowrap}
.prep-doc .rail a:hover{color:var(--ink);border-color:var(--jade-line)}
.prep-doc .rail a b{color:var(--jade);font-weight:500}
.prep-doc .mast{padding-block:44px 22px;border-bottom:3px double var(--line);margin-bottom:28px}
.prep-doc .eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.prep-doc .mast h1{font-family:var(--display);font-weight:400;font-size:clamp(40px,8vw,68px);line-height:1.02;margin-top:10px;letter-spacing:-.01em}
.prep-doc .mast .sub{font-family:var(--read);font-style:italic;font-size:19px;color:var(--muted);margin-top:10px;max-width:60ch}
.prep-doc .meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.prep-doc .chip{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:11.5px;letter-spacing:.02em;padding:3px 9px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--muted);white-space:nowrap}
.prep-doc .chip.time{border-color:var(--slate-line);color:var(--slate);background:var(--slate-tint)}
.prep-doc .chip.dc{border-color:var(--copper-line);color:var(--copper);background:var(--copper-tint);font-weight:500}
.prep-doc .chip.pc{font-weight:500}
.prep-doc .chip.boon{color:var(--boon);border-color:color-mix(in srgb,var(--boon) 45%,transparent)}
.prep-doc .chip.orek{color:var(--orek);border-color:color-mix(in srgb,var(--orek) 45%,transparent)}
.prep-doc .chip.vali{color:var(--vali);border-color:color-mix(in srgb,var(--vali) 45%,transparent)}
.prep-doc .open{font-family:var(--mono);font-size:11px;font-weight:500;color:var(--copper);background:var(--copper-tint);border:1px solid var(--copper-line);border-radius:4px;padding:0 5px;white-space:nowrap}
.prep-doc .new{font-family:var(--mono);font-size:10.5px;color:var(--muted);border:1px solid var(--line);border-radius:4px;padding:0 4px}
.prep-doc .prep{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,380px),1fr));gap:14px;margin-bottom:22px}
.prep-doc .panel{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:16px 18px;min-width:0}
.prep-doc .panel h3{font-family:var(--display-sc);font-weight:400;font-size:19px;margin-bottom:8px;color:var(--ink)}
.prep-doc .panel ul, .prep-doc .panel ol{margin:0;padding-left:18px;display:grid;gap:5px}
.prep-doc .panel.wide{grid-column:1/-1}
.prep-doc .small{font-size:13px;color:var(--muted)}
.prep-doc .clocks{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,190px),1fr));gap:12px}
.prep-doc .clock{display:grid;gap:6px;min-width:0}
.prep-doc .clock .name{font-weight:600;font-size:13.5px}
.prep-doc .clock .goal{font-size:12.5px;color:var(--muted)}
.prep-doc .pips{display:flex;gap:4px;flex-wrap:wrap}
.prep-doc .pip{width:22px;height:14px;border-radius:3px;border:1px solid var(--jade-line);background:transparent;cursor:pointer;padding:0}
.prep-doc .pip.on{background:var(--jade);border-color:var(--jade)}
.prep-doc .clock.dawn .pip{width:30px;height:18px;border-color:var(--copper-line)}
.prep-doc .clock.dawn .pip.on{background:var(--copper);border-color:var(--copper)}
.prep-doc .dawn-table td:first-child{font-family:var(--mono);font-size:12px;color:var(--copper);width:44px}
.prep-doc .flow{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:4px}
.prep-doc .flow .node{font-size:12.5px;padding:5px 10px;border-radius:5px;border:1px solid var(--line);background:var(--surface);text-decoration:none;color:var(--ink)}
.prep-doc .flow .node.dusk{border-color:var(--copper-line);background:var(--copper-tint);color:var(--copper);font-weight:600}
.prep-doc .flow .node.night{border-color:var(--slate-line);background:var(--slate-tint);color:var(--slate)}
.prep-doc .flow .group{display:flex;flex-wrap:wrap;gap:6px;padding:6px;border:1px dashed var(--jade-line);border-radius:7px}
.prep-doc .flow .arrow{color:var(--muted);font-family:var(--mono)}
.prep-doc .tablewrap{overflow-x:auto;margin-top:4px}
.prep-doc table{border-collapse:collapse;width:100%;font-size:13px}
.prep-doc th, .prep-doc td{text-align:left;vertical-align:top;padding:7px 9px;border-bottom:1px solid var(--line)}
.prep-doc th{font-family:var(--mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:500}
.prep-doc td:first-child{font-weight:500;white-space:nowrap}
.prep-doc td.hi{font-weight:600}
.prep-doc th.boon{color:var(--boon)}
.prep-doc th.orek{color:var(--orek)}
.prep-doc th.vali{color:var(--vali)}
.prep-doc .scene{margin-top:56px;scroll-margin-top:60px}
.prep-doc .scene-head{display:grid;grid-template-columns:auto 1fr;gap:4px 16px;align-items:end;padding-bottom:12px;border-bottom:1.5px solid var(--ink)}
.prep-doc .scene-num{font-family:var(--display);font-size:64px;line-height:.8;color:var(--jade);grid-row:span 2}
.prep-doc .scene-head h2{font-family:var(--display);font-weight:400;font-size:clamp(28px,5vw,38px);line-height:1.05}
.prep-doc .scene-head .chips{display:flex;flex-wrap:wrap;gap:6px}
.prep-doc .scene-head > *{min-width:0}
.prep-doc .scene-head .chip{white-space:normal}
.prep-doc .scene-sub{margin-top:12px;display:flex;flex-wrap:wrap;gap:6px 14px;font-size:13px;color:var(--muted)}
.prep-doc .scene-sub b{color:var(--ink);font-weight:600}
.prep-doc h3.beat{font-family:var(--display-sc);font-weight:400;font-size:21px;margin-top:30px;margin-bottom:10px;padding-bottom:4px;border-bottom:1px solid var(--line);display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.prep-doc h3.beat .chip{font-family:var(--mono)}
.prep-doc .stack{display:grid;gap:12px}
.prep-doc .dmnote{font-size:14.5px}
.prep-doc .dmnote+.dmnote{margin-top:8px}
.prep-doc ul.dmnote{margin:0;padding-left:20px;display:grid;gap:5px}
.prep-doc .leadin{margin-top:18px;background:var(--copper-tint);border:1px solid var(--copper-line);border-radius:6px;padding:14px 16px}
.prep-doc .leadin .lbl{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--copper);margin-bottom:6px}
.prep-doc .leadin ul{margin:0;padding-left:18px;display:grid;gap:4px}
.prep-doc .ra{position:relative;background:var(--jade-tint);border:1px solid var(--jade-line);border-radius:3px;padding:26px 22px 18px;margin-top:12px}
.prep-doc .ra::before{content:attr(data-label);position:absolute;top:-1px;left:16px;transform:translateY(-50%);font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--jade);background:var(--surface);border:1px solid var(--jade-line);border-radius:3px;padding:1px 8px}
.prep-doc .ra p{font-family:var(--read);font-size:17.5px;line-height:1.7;max-width:66ch}
.prep-doc .ra p+p{margin-top:.8em}
.prep-doc .ra .q{font-style:italic}
.prep-doc .ra.short p{font-size:16.5px}
.prep-doc .ra .ear{font-variant:small-caps;letter-spacing:.03em;font-weight:500}
.prep-doc .check{border:1px solid var(--line);background:var(--surface);border-radius:6px;margin-top:14px;overflow:hidden}
.prep-doc .check-h{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line)}
.prep-doc .check-h .t{font-weight:600}
.prep-doc .check-h .chip, .prep-doc .scene-sub .chip, .prep-doc h3.beat .chip{white-space:normal}
.prep-doc .check-b{padding:12px 14px;display:grid;gap:10px}
.prep-doc .prompt{font-family:var(--read);font-style:italic;font-size:16.5px;line-height:1.6}
.prep-doc .outcome{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:start}
.prep-doc .outcome .mark{font-family:var(--mono);font-size:11px;font-weight:500;padding:2px 7px;border-radius:3px;margin-top:3px;white-space:nowrap}
.prep-doc .outcome.ok .mark{background:var(--jade-tint);color:var(--jade);border:1px solid var(--jade-line)}
.prep-doc .outcome.no .mark{background:var(--copper-tint);color:var(--copper);border:1px solid var(--copper-line)}
.prep-doc .outcome .txt{min-width:0}
.prep-doc .outcome .say{font-family:var(--read);font-size:16px;line-height:1.6}
.prep-doc .outcome .cost{font-size:13.5px;color:var(--muted);margin-top:4px}
.prep-doc .outcome .cost b{color:var(--copper);font-weight:600}
.prep-doc .npc{display:grid;grid-template-columns:minmax(0,1fr);gap:4px;border:1px solid var(--slate-line);background:var(--slate-tint);border-radius:6px;padding:12px 14px;margin-top:12px}
.prep-doc .npc .nm{font-family:var(--display);font-size:21px;line-height:1.1}
.prep-doc .npc .role{font-size:12.5px;color:var(--slate);font-family:var(--mono)}
.prep-doc .npc dl{display:grid;grid-template-columns:max-content 1fr;gap:3px 12px;margin:6px 0 0;font-size:13.5px}
.prep-doc .npc dt{font-family:var(--mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);padding-top:2px}
.prep-doc .npc dd{margin:0;min-width:0}
.prep-doc .npc .line{font-family:var(--read);font-style:italic;font-size:15.5px;margin-top:4px}
.prep-doc .ref{margin-top:14px;border:1px solid var(--line);border-radius:6px;background:var(--surface);overflow:hidden}
.prep-doc .ref .ref-h{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);padding:8px 14px;border-bottom:1px solid var(--line)}
.prep-doc .ref table{font-size:13.5px}
.prep-doc .ref td:first-child{width:118px;font-family:var(--mono);font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);font-weight:500;white-space:normal}
.prep-doc .ref tr:last-child td{border-bottom:0}
.prep-doc .who{display:grid;gap:3px}
.prep-doc .who span b{font-weight:600}
.prep-doc .handout{margin:14px auto 0;max-width:460px;background:var(--paper);color:var(--paper-ink);border:1px solid var(--paper-line);box-shadow:0 1px 0 var(--paper-line),0 8px 18px -12px rgba(0,0,0,.35);padding:22px 24px;transform:rotate(-.6deg);font-family:var(--display);font-size:19px;line-height:1.45}
.prep-doc .handout .hl{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--paper-label);margin-bottom:8px;font-style:normal}
.prep-doc .handout.ledger{font-family:var(--mono);font-size:13.5px;transform:rotate(.4deg)}
.prep-doc .handout.ledger .hl{font-size:10px}
.prep-doc .handout + .handout{margin-top:18px}
.prep-doc details.art{margin-top:14px;border:1px dashed var(--line);border-radius:6px;padding:8px 12px;background:transparent}
.prep-doc details.art summary{cursor:pointer;font-family:var(--mono);font-size:12px;color:var(--muted);list-style:none;display:flex;justify-content:space-between;gap:10px;align-items:center}
.prep-doc details.art summary::-webkit-details-marker{display:none}
.prep-doc details.art summary > span:first-of-type{margin-right:auto}
.prep-doc details.art summary::before{content:"▸ ";}
.prep-doc details.art[open] summary::before{content:"▾ ";}
.prep-doc details.art p{font-size:13.5px;margin-top:8px;color:var(--ink)}
.prep-doc .copy{font-family:var(--mono);font-size:11px;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:4px;padding:3px 9px;cursor:pointer}
.prep-doc .copy:hover{border-color:var(--jade-line)}
.prep-doc details.art .artp{font-size:13.5px;line-height:1.65;margin-top:10px;color:var(--ink);max-width:none}
.prep-doc details.art .artp b{color:var(--jade);font-weight:600}
.prep-doc .items{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:10px;margin-top:12px}
.prep-doc .itm{border:1px solid var(--line);border-radius:6px;background:var(--surface);padding:10px 12px;display:grid;gap:6px;min-width:0;align-content:start}
.prep-doc .itm .in{font-family:var(--display);font-size:18px;line-height:1.15}
.prep-doc .itm .it{font-family:var(--mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.prep-doc .itm .id{font-size:13px;line-height:1.5}
.prep-doc .itm .id b{font-weight:600}
.prep-doc .fx-row{display:flex;flex-wrap:wrap;gap:6px;margin-top:2px}
.prep-doc .fx{font-family:var(--mono);font-size:11px;border:1px solid var(--slate-line);background:var(--slate-tint);color:var(--slate);border-radius:4px;padding:3px 9px;cursor:pointer;white-space:nowrap}
.prep-doc .fx:hover{border-color:var(--slate)}
.prep-doc .fx-inline{display:inline-flex;gap:6px;margin-left:6px;vertical-align:middle;flex-wrap:wrap}
.prep-doc .exits{margin-top:16px;padding-top:12px;border-top:1px solid var(--line);display:grid;gap:10px;font-size:13px}
.prep-doc .exits-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.prep-doc .exits .lbl{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.prep-doc .lead{font-family:var(--sans);font-size:13px;cursor:pointer;border:1px solid var(--jade-line);color:var(--jade);background:var(--jade-tint);border-radius:999px;padding:3px 11px}
.prep-doc .lead:hover{border-color:var(--jade)}
.prep-doc .lead[aria-expanded="true"]{background:var(--jade);color:var(--surface);border-color:var(--jade)}
.prep-doc .lead::after{content:" ▾";font-size:10px;opacity:.7}
.prep-doc .lead[aria-expanded="true"]::after{content:" ▴"}
.prep-doc .tpanel{border:1px solid var(--jade-line);border-radius:6px;background:var(--surface);padding:12px 14px;display:grid;gap:8px}
.prep-doc .tp-h{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;align-items:baseline}
.prep-doc .tp-h span{font-family:var(--display-sc);font-size:17px;color:var(--ink)}
.prep-doc .tp-h a{font-family:var(--mono);font-size:11.5px;text-decoration:none;border:1px solid var(--jade-line);border-radius:999px;padding:2px 9px;color:var(--jade)}
.prep-doc .nudge{font-size:14px;line-height:1.55}
.prep-doc .nudge b{font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--copper);font-weight:500;margin-right:4px}
.prep-doc .tpanel .ra{margin-top:10px}
.prep-doc details.leads{margin-top:16px;border-style:solid;border-color:var(--jade-line);background:var(--jade-tint)}
.prep-doc details.leads summary{color:var(--jade)}
.prep-doc details.leads summary .cnt{font-size:11px;color:var(--muted)}
.prep-doc details.leads .exits{margin-top:10px;padding-top:10px;border-top:1px solid var(--jade-line)}
.prep-doc .nudge strong{font-weight:600}
.prep-doc .handoff{font-family:var(--mono);font-size:11px;letter-spacing:.04em;color:var(--muted)}
.prep-doc .two{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px;margin-top:14px}
.prep-doc .box{border:1px solid var(--line);border-radius:6px;background:var(--surface);padding:12px 14px;min-width:0}
.prep-doc .box h4{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:500;margin-bottom:8px}
.prep-doc .box ul{margin:0;padding-left:18px;display:grid;gap:6px;font-size:14px}
.prep-doc .box p{font-size:14px}
.prep-doc .branch{display:grid;gap:8px;font-size:14px}
.prep-doc .branch div{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.6fr);gap:10px;padding-bottom:8px;border-bottom:1px solid var(--line)}
.prep-doc .branch div:last-child{border-bottom:0;padding-bottom:0}
.prep-doc .branch i{font-style:normal;font-weight:600}
.prep-doc .foot-meta{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:10px;font-size:12.5px;color:var(--muted)}
.prep-doc .foot-meta b{color:var(--ink);font-weight:600}
.prep-doc .lock{margin-top:16px;border:1.5px solid var(--copper);border-radius:6px;padding:14px 16px;background:var(--surface)}
.prep-doc .lock .lbl{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--copper);margin-bottom:6px;font-weight:500}
.prep-doc .lock ul{margin:6px 0 0;padding-left:18px;display:grid;gap:5px;font-size:14px}
.prep-doc .six td:first-child{white-space:normal;width:30%}
.prep-doc .six td:nth-child(2){font-family:var(--mono);font-size:12px;color:var(--copper);white-space:normal;width:26%}
.prep-doc .stat{border:1px solid var(--copper-line);background:var(--surface);border-radius:6px;padding:12px 14px;margin-top:12px;font-size:13.5px;display:grid;gap:6px}
.prep-doc .stat .sn{font-family:var(--display);font-size:19px}
.prep-doc .stat .sb{font-family:var(--mono);font-size:11.5px;color:var(--copper)}
.prep-doc .stat ul{margin:0;padding-left:18px;display:grid;gap:4px}
.prep-doc footer{margin-top:60px;padding-top:16px;border-top:3px double var(--line);font-size:13px;color:var(--muted)}
.prep-doc{scroll-behavior:smooth}
.prep-doc .ref.qa td{vertical-align:top}
.prep-doc .ref.qa td:first-child{width:22%;font-family:var(--sans);font-size:13.5px;letter-spacing:0;text-transform:none;color:var(--ink);font-weight:600;white-space:normal}
.prep-doc .ref.qa td:nth-child(2){font-family:var(--read);font-size:15.5px;font-style:italic;line-height:1.55}
.prep-doc .ref.qa td:nth-child(3){font-size:12.5px;color:var(--muted);width:24%}
.prep-doc .ref.qa tr:last-child td{border-bottom:0}
.prep-doc details.art.music{border-color:var(--slate-line)}
.prep-doc details.art.music summary{color:var(--slate)}
.prep-doc details.art.music summary .len{font-family:var(--mono);font-size:10.5px;color:var(--muted);margin-left:auto;margin-right:8px}
.prep-doc details.art.music .artp{font-family:var(--read);font-size:15px;font-style:italic}
.prep-doc details.art + details.art{margin-top:8px}
.prep-doc details.opt{margin-top:18px;border:1.5px dashed var(--copper-line);border-radius:6px;padding:10px 14px;background:var(--surface)}
.prep-doc details.opt > summary{cursor:pointer;list-style:none;display:flex;flex-wrap:wrap;align-items:baseline;gap:8px}
.prep-doc details.opt > summary::-webkit-details-marker{display:none}
.prep-doc details.opt > summary .ot{font-family:var(--display-sc);font-size:20px;color:var(--copper)}
.prep-doc details.opt > summary .ot::before{content:"▸ "}
.prep-doc details.opt[open] > summary .ot::before{content:"▾ "}
.prep-doc details.opt > summary .os{font-size:13px;color:var(--muted);flex-basis:100%}
.prep-doc details.art.map{border-color:var(--copper-line)}
.prep-doc details.art.map summary{color:var(--copper)}
.prep-doc details.art.map .artp b{color:var(--copper)}
.prep-doc .enc{border:1.5px solid var(--copper-line);border-radius:6px;background:var(--surface);margin-top:14px;overflow:hidden}
.prep-doc .enc-h{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 14px;background:var(--copper-tint);border-bottom:1px solid var(--copper-line)}
.prep-doc .enc-h .t{font-family:var(--display-sc);font-size:19px;color:var(--ink)}
.prep-doc .enc-b{padding:12px 14px;display:grid;gap:10px;font-size:14px}
.prep-doc .enc-b dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:6px 14px;margin:0}
.prep-doc .enc-b dt{font-family:var(--mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--copper);padding-top:2px}
.prep-doc .enc-b dd{margin:0;min-width:0}
.prep-doc .enc-b ul{margin:0;padding-left:18px;display:grid;gap:4px}
.prep-doc .npc details.art{background:var(--surface)}
.prep-doc .flow .group .arrow{font-size:12px}
